import sys

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    print('\n'.join('YES' if is_prime(int(data[1 + i])) else 'NO' for i in range(t)))

main()

